mapper.select:
SELECT c.*, u.name AS creatorName, u.avatar AS creatorAvatar, r.type AS userRatingType,
pu.id AS replyToUserId, pu.name AS replyToName FROM comments c LEFT JOIN users u ON c.creator = u.id LEFT JOIN ratings r ON r.target = 'COMMENT' AND r.target_id = c.id AND r.creator = #{userId}
LEFT JOIN comments pc ON pc.id = c.target_id AND c.target = 'COMMENT' LEFT JOIN users pu ON pu.id = pc.creator
WHERE c.root_type = 'POST' AND c.root_id = #{postId} AND c.parent_id IN
#{parentId}
AND c.is_deleted = 0 ORDER BY c.create_time ASC
